const alarm = {
  time: "7:00",
  getRing() {
    return () => `ring at ${this.time}`;
  },
};

const late = { time: "9:30" };
const ring = alarm.getRing();
const lateRing = alarm.getRing.call(late);

late.ring = ring;

console.log(late.ring());
console.log(ring.call(late));
console.log(lateRing());
